import { headers } from 'next/headers';

interface AnalyticsData {
  views: number;
  uniqueVisitors: number;
  bounceRate: number;
}

interface Notification {
  id: number;
  message: string;
  read: boolean;
}

interface SettingsData {
  theme: string;
  notificationsEnabled: boolean;
  language?: string;
}

export default async function Dashboard() {
  // Construct absolute URL for server-side fetching
  const headersList = await headers();
  const host = headersList.get('host') || 'localhost:3000';
  const protocol = host.includes('localhost') ? 'http' : 'https';
  const baseUrl = `${protocol}://${host}`;

  try {
    const [analyticsRes, notificationsRes, settingsRes] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`, { cache: 'no-store' }),
      fetch(`${baseUrl}/api/notifications`, { cache: 'no-store' }),
      fetch(`${baseUrl}/api/settings`, { cache: 'no-store' })
    ]);

    if (!analyticsRes.ok || !notificationsRes.ok || !settingsRes.ok) {
      throw new Error('Failed to fetch dashboard data');
    }

    const analytics: AnalyticsData = await analyticsRes.json();
    const notifications: Notification[] = await notificationsRes.json();
    const settings: SettingsData = await settingsRes.json();

    return (
      <div style={{ padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
        <h2 style={{ fontSize: '24px', marginBottom: '20px' }}>Dashboard Overview</h2>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '40px' }}>
          <div style={{ padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
            <h3>Analytics</h3>
            <p><strong>Total Views:</strong> {analytics.views.toLocaleString()}</p>
            <p><strong>Unique Visitors:</strong> {analytics.uniqueVisitors.toLocaleString()}</p>
            <p><strong>Bounce Rate:</strong> {analytics.bounceRate}%</p>
          </div>

          <div style={{ padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
            <h3>Settings</h3>
            <p><strong>Theme:</strong> {settings.theme}</p>
            <p><strong>Notifications:</strong> {settings.notificationsEnabled ? 'Enabled' : 'Disabled'}</p>
            {settings.language && <p><strong>Language:</strong> {settings.language}</p>}
          </div>
        </div>

        <div style={{ padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
          <h3>Notifications</h3>
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {notifications.map((notification) => (
              <li key={notification.id} style={{ padding: '10px', borderBottom: '1px solid #eee', color: notification.read ? '#666' : '#000' }}>
                {notification.read ? 'Draft: ' : 'New: '} {notification.message}
              </li>
            ))}
          </ul>
        </div>
      </div>
    );
  } catch (error) {
    console.error('Error loading dashboard:', error);
    return (
      <div style={{ padding: '20px', color: 'red' }}>
        <h2>Error loading dashboard data</h2>
        <p>Please try again later.</p>
      </div>
    );
  }
}

